<?php
require_once __DIR__.'/config/app.php';
$q=trim($_GET['q']??'');$category=max(0,(int)($_GET['category']??0));$min=max(0,(float)($_GET['min']??0));$max=max(0,(float)($_GET['max']??0));$sort=$_GET['sort']??'newest';$page=max(1,(int)($_GET['page']??1));$perPage=12;
$where=['p.is_active=1'];$params=[];
if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR p.description LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($category){$where[]='p.category_id=?';$params[]=$category;}if($min>0){$where[]='p.price>=?';$params[]=$min;}if($max>0){$where[]='p.price<=?';$params[]=$max;}
$order=match($sort){'price_low'=>'p.price ASC','price_high'=>'p.price DESC',default=>'p.created_at DESC,p.id DESC'};$whereSql=implode(' AND ',$where);
$count=db()->prepare("SELECT COUNT(*) FROM products p WHERE $whereSql");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$stmt=db()->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE $whereSql ORDER BY $order LIMIT $perPage OFFSET $offset");$stmt->execute($params);$products=$stmt->fetchAll();$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$pageTitle='Belanja';require APP_ROOT.'/includes/header.php';
?>
<section class="page-hero"><div class="container"><div class="section-kicker">Katalog EKO CEPER</div><h1>Belanja produk pilihan</h1><p class="text-muted mb-0">Cari dan pilih produk yang sesuai dengan kebutuhan Anda.</p></div></section>
<section class="pb-5"><div class="container"><div class="row g-4"><aside class="col-lg-3" id="categories"><form class="filter-card" method="get"><h5 class="fw-bold mb-3"><i class="bi bi-funnel me-2"></i>Filter</h5><div class="mb-3"><label class="form-label small fw-semibold">Cari produk</label><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Nama atau SKU..."></div><div class="mb-3"><label class="form-label small fw-semibold">Kategori</label><select class="form-select" name="category"><option value="0">Semua kategori</option><?php foreach($categories as $cat):?><option value="<?= $cat['id'] ?>" <?= $category==(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach;?></select></div><div class="row g-2 mb-3"><div class="col-6"><label class="form-label small">Harga min.</label><input class="form-control" type="number" name="min" value="<?= $min?:'' ?>"></div><div class="col-6"><label class="form-label small">Harga maks.</label><input class="form-control" type="number" name="max" value="<?= $max?:'' ?>"></div></div><div class="mb-3"><label class="form-label small fw-semibold">Urutkan</label><select class="form-select" name="sort"><option value="newest">Terbaru</option><option value="price_low" <?= $sort==='price_low'?'selected':'' ?>>Harga termurah</option><option value="price_high" <?= $sort==='price_high'?'selected':'' ?>>Harga termahal</option></select></div><button class="btn btn-primary w-100">Terapkan</button><a class="btn btn-light w-100 mt-2" href="<?= url('shop.php') ?>">Reset</a></form></aside><div class="col-lg-9"><div class="d-flex justify-content-between align-items-center mb-3"><div><strong><?= $total ?></strong> produk ditemukan</div></div><?php if(!$products):?><div class="content-card empty-state"><i class="bi bi-search"></i><h4 class="fw-bold mt-3">Produk tidak ditemukan</h4><p class="text-muted">Coba ubah kata pencarian atau filter Anda.</p><a class="btn btn-primary" href="<?= url('shop.php') ?>">Lihat semua produk</a></div><?php else:?><div class="row g-4"><?php foreach($products as $product):?><div class="col-6 col-md-4"><?php require APP_ROOT.'/includes/product-card.php';?></div><?php endforeach;?></div><?php if($pages>1):?><nav class="mt-5"><ul class="pagination justify-content-center"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?= $i===$page?'active':'' ?>"><a class="page-link" href="?<?= e(query_string(['page'=>$i])) ?>"><?= $i ?></a></li><?php endfor;?></ul></nav><?php endif;?><?php endif;?></div></div></div></section>
<?php require APP_ROOT.'/includes/footer.php';?>
